import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, EventEmitter, inject, Input, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { required } from '@angular/forms/signals';
import { CharacterSheet } from '../../model/character-sheet-model';
import { FormulaType } from '../../model/formula-type.enum';
import { JsonPatch } from '../../model/json-patch.model';
import { LibraryStoreService } from '../../services/library-store.service';
import { StatusEffect } from '../../model/status-effect.model';
import { TrueStatsService } from '../../services/true-stats.service';

@Component({
  selector: 'app-currentstat',
  imports: [CommonModule, FormsModule],
  templateUrl: './currentstat.component.html',
  styleUrl: './currentstat.component.css',
})
export class CurrentstatComponent {
  @Input() sheet!: CharacterSheet;
  @Input() name!: string;
  @Input() current!: number;
  @Input() color!: string;
  @Input() base!: number;
  @Input() bonus!: number;
  @Input() formula!: FormulaType;
  constructor(private cd: ChangeDetectorRef) {}
  private libraryStore = inject(LibraryStoreService);
  private trueStats = inject(TrueStatsService);

  // Map formula types to stat keys for skill modifiers
  private getStatusKey(): 'mana' | 'life' | 'energy' | null {
    switch (this.formula) {
      case FormulaType.LIFE:
        return 'life';
      case FormulaType.ENERGY:
        return 'energy';
      case FormulaType.MANA:
        return 'mana';
      default:
        return null;
    }
  }

  get effectBonus(): number {
    const statusKey = this.getStatusKey();
    if (!statusKey) return 0;

    let total = 0;

    // Add bonuses from skills
    if (this.sheet.skills) {
      for (const skill of this.sheet.skills) {
        if (skill.statModifiers) {
          for (const modifier of skill.statModifiers) {
            if (modifier.stat === statusKey) {
              const multiplier = skill.level || 1;
              total += modifier.amount * multiplier;
            }
          }
        }
      }
    }

    // Add bonuses from equipped items
    if (this.sheet.equipment) {
      for (const item of this.sheet.equipment) {
        if (item.statModifiers) {
          for (const modifier of item.statModifiers) {
            if (modifier.stat === statusKey) {
              total += modifier.amount;
            }
          }
        }
      }
    }

    // Add bonuses from active status effects
    if (this.sheet.activeStatusEffects) {
      for (const active of this.sheet.activeStatusEffects) {
        const effect = this.resolveStatusEffect(active.statusEffectId, active.customEffect);
        if (effect?.statModifiers) {
          for (const modifier of effect.statModifiers) {
            if (modifier.stat === statusKey) {
              const stacks = active.stacks || 1;
              total += modifier.amount * stacks;
            }
          }
        }
      }
    }

    return total;
  }

  private resolveStatusEffect(statusEffectId: string, customEffect?: StatusEffect): StatusEffect | undefined {
    if (customEffect) return customEffect;
    for (const lib of this.libraryStore.allLibraries) {
      const found = lib.statusEffects?.find((se: StatusEffect) => se.id === statusEffectId);
      if (found) return found;
    }
    return undefined;
  }

  get effectSources(): string[] {
    const statusKey = this.getStatusKey();
    if (!statusKey) return [];

    const sources: string[] = [];

    // Collect sources from skills
    if (this.sheet.skills) {
      for (const skill of this.sheet.skills) {
        if (skill.statModifiers) {
          for (const modifier of skill.statModifiers) {
            if (modifier.stat === statusKey) {
              const multiplier = skill.level || 1;
              const amount = modifier.amount * multiplier;
              const sign = amount >= 0 ? '+' : '';
              sources.push(`${skill.name}: ${sign}${amount}`);
            }
          }
        }
      }
    }

    // Collect sources from equipment
    if (this.sheet.equipment) {
      for (const item of this.sheet.equipment) {
        if (item.statModifiers) {
          for (const modifier of item.statModifiers) {
            if (modifier.stat === statusKey) {
              const sign = modifier.amount >= 0 ? '+' : '';
              sources.push(`${item.name}: ${sign}${modifier.amount}`);
            }
          }
        }
      }
    }

    // Collect sources from active status effects
    if (this.sheet.activeStatusEffects) {
      for (const active of this.sheet.activeStatusEffects) {
        const effect = this.resolveStatusEffect(active.statusEffectId, active.customEffect);
        if (effect?.statModifiers) {
          for (const modifier of effect.statModifiers) {
            if (modifier.stat === statusKey) {
              const stacks = active.stacks || 1;
              const amount = modifier.amount * stacks;
              const sign = amount >= 0 ? '+' : '';
              const name = active.customName ?? effect.name ?? active.statusEffectId;
              sources.push(`${name}: ${sign}${amount}`);
            }
          }
        }
      }
    }

    return sources;
  }

  get statusMax(): number {
    // Delegate to the central calculator so the stat contribution (CON/GES/INT × 5)
    // reflects skills, equipment and status effects — not the stale cached `.current`.
    if (this.getStatusKey()) {
      return this.trueStats.calculateResourceMax(this.sheet, this.formula);
    }
    return this.base + this.bonus + this.effectBonus;
  }

  get barClass(): string {
    switch (this.formula) {
      case FormulaType.LIFE:
        return 'health';
      case FormulaType.ENERGY:
        return 'energy';
      case FormulaType.MANA:
        return 'mana';
      default:
        return '';
    }
  }

  @Output() patch = new EventEmitter<JsonPatch>();
  updateBase(path: string, value: any) {
    this.base = value;
    this.patch.emit({ path: path, value });
    this.cd.detectChanges();
  }
  updateCurrent(path: string, value: any) {
    this.current = value;
    this.patch.emit({ path: path, value });
    this.cd.detectChanges();
  }
  updateBonus(path: string, value: any) {
    this.bonus= value;
    this.patch.emit({ path, value });
    this.cd.detectChanges();
  }
}
